class Solution {
    long long MOD = 1e9 + 7;
    long long power(long long base, long long exp) {
        long long res = 1;
        base %= MOD;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2;
        }
        return res;
    }
public:
    int stringCount(int n) {
        if (n < 4) return 0;
        long long total = power(26, n);
        long long not_l = power(25, n);
        long long not_t = power(25, n);
        long long few_e = (power(25, n) + (long long) n * power(25, n - 1)) % MOD;
        long long not_lt = power(24, n);
        long long not_le = (power(24, n) + (long long) n * power(24, n - 1)) % MOD;
        long long not_te = (power(24, n) + (long long) n * power(24, n - 1)) % MOD;
        long long not_lte = (power(23, n) + (long long) n * power(23, n - 1)) % MOD;
        long long invalid = (not_l + not_t + few_e - not_lt - not_le - not_te + not_lte) % MOD;
        return (total - invalid + MOD) % MOD;
    }
};

class Solution {
    long MOD = 1_000_000_007L;
    long power(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }
    public int stringCount(int n) {
        if (n < 4) return 0;
        long total = power(26, n);
        long notL = power(25, n);
        long notT = power(25, n);
        long fewE = (power(25, n) + (long) n * power(25, n - 1)) % MOD;
        long notLT = power(24, n);
        long notLE = (power(24, n) + (long) n * power(24, n - 1)) % MOD;
        long notTE = (power(24, n) + (long) n * power(24, n - 1)) % MOD;
        long notLTE = (power(23, n) + (long) n * power(23, n - 1)) % MOD;
        long invalid = (notL + notT + fewE - notLT - notLE - notTE + notLTE) % MOD;
        return (int) ((total - invalid + MOD) % MOD);
    }
}

