var stringCount = function(n) {
    if (n < 4) return 0;
    const MOD = 1000000007n;
    function power(base, exp) {
        let res = 1n;
        base = BigInt(base) % MOD;
        let e = BigInt(exp);
        while (e > 0n) {
            if ((e & 1n) === 1n) res = (res * base) % MOD;
            base = (base * base) % MOD;
            e >>= 1n;
        }
        return res;
    }
    const bn = BigInt(n);
    const total = power(26n, n);
    const notL = power(25n, n);
    const notT = power(25n, n);
    const fewE = (power(25n, n) + bn * power(25n, n - 1)) % MOD;
    const notLT = power(24n, n);
    const notLE = (power(24n, n) + bn * power(24n, n - 1)) % MOD;
    const notTE = (power(24n, n) + bn * power(24n, n - 1)) % MOD;
    const notLTE = (power(23n, n) + bn * power(23n, n - 1)) % MOD;
    const invalid = (notL + notT + fewE - notLT - notLE - notTE + notLTE) % MOD;
    return Number((total - invalid + MOD) % MOD);
};
